function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}function modal(title,body,fn){$('#modal').classList.remove('theme-picker');$('#modalBody').innerHTML=`<div class="modal-title">${esc(title)}</div>${body}<div class="modal-submit"><button class="btn ghost" value="cancel">Cancel</button><button class="btn primary" id="modalSave" type="button">Save</button></div>`;$('#modal').showModal();$('#modalSave').onclick=async()=>{try{await fn();$('#modal').close()}catch(e){toast(e.message)}}}async function load(){const paths={dashboard:dashboard,tutor:tutor,courses:courses,notes:notes,flashcards:flashcards,quizzes:quizzes,memory:memory,analytics:analytics,settings:settings,calendar:calendar};$('#crumb').textContent={dashboard:'Overview',tutor:'AI tutor',courses:'My learning',notes:'Notes & library',flashcards:'Flashcards',quizzes:'Quizzes & exams',memory:'Learning memory',analytics:'Insights',settings:'Settings',calendar:'Study calendar'}[view]||view;$$('.nav-item[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));try{await paths[view]();if(view==='dashboard')await appendUpcoming()}catch(e){$('#content').innerHTML=`<div class="card empty"><strong>Couldn't load this page</strong>${esc(e.message)}<button class="btn" onclick="load()">Try again</button></div>`}}
function go(v){view=v;history.replaceState(null,'','#'+v);$('#sidebar').classList.remove('open');load()}$('#sidebar').addEventListener('click',e=>{const theme=e.target.closest('[data-theme-picker]');if(theme){openThemePicker();return}const b=e.target.closest('[data-view]');if(b)go(b.dataset.view)});window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(v&&v!==view){view=v;load()}});$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#themeBtn').onclick=openThemePicker;const savedTheme=localStorage.getItem('studyspace-theme')||(localStorage.getItem('theme')==='light'?'paper':'midnight');applyTheme(savedTheme);$('#searchBtn').onclick=()=>{modal('Search your workspace',`<div class="field"><label>Find notes, memories, courses, and conversations</label><input id="searchAll" placeholder="Search everything..."></div><div id="searchResults" class="modal-note">Type to search saved learning memory and notes.</div>`,async()=>{});$('#modalSave').style.display='none';$('#searchAll').oninput=async e=>{let q=e.target.value;if(!q)return;const [m,n]=await Promise.all([api('/memories?q='+encodeURIComponent(q)),api('/notes')]);const results=[...m.map(x=>['Memory',x.content]),...n.filter(x=>(x.title+x.body).toLowerCase().includes(q.toLowerCase())).map(x=>['Note',x.title])];$('#searchResults').innerHTML=results.map(x=>`<div class="memory-row"><span class="tag">${x[0]}</span><div>${esc(x[1])}</div></div>`).join('')||'No matches yet.'}};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#searchBtn').click()}});
async function shared(){const [subs,status,due]=await Promise.all([api('/subjects'),api('/status'),api('/flashcards/due')]);$('#sideSubjects').innerHTML=subs.map(s=>`<button class="subject-link" data-subject="${s.id}"><i style="--c:${esc(s.color)}"></i>${esc(s.name)}</button>`).join('');$('#sideSubjects').onclick=e=>{const b=e.target.closest('[data-subject]');if(b){studySubject=Number(b.dataset.subject);go('tutor')}};$('#geminiStatus').textContent=status.aiConfigured?'Gemini connected · '+status.model:'Add API key to enable AI';$('.status-dot').classList.toggle('ready',status.aiConfigured);$('#dueBadge').textContent=due.length?due.length:'';return{subs,status,due}}
async function dashboard(){const [d,side]=await Promise.all([api('/dashboard'),shared()]);const h=new Date().getHours(),greeting=h<12?'Good morning':h<18?'Good afternoon':'Good evening';const hours=Math.floor(d.stats.seconds/3600),minutes=Math.floor(d.stats.seconds%3600/60);$('#content').innerHTML=`<div class="title-row"><div><div class="eyebrow">SUNDAY, NOVEMBER 15</div><h1>Your learning, in rhythm.</h1><div class="subline">A little progress today adds up to a lot over time.</div></div><div class="title-actions"><button class="btn" onclick="startSession()">◷ Start study session</button><button class="btn primary" onclick="go('tutor')">✧ Ask your tutor</button></div></div><section class="welcome"><div><h2>${greeting}, learner <span style="color:var(--green)">✳</span></h2><p>Your space is ready. Pick up where you left off or start something new.</p></div><button class="btn primary" onclick="go('courses')">Continue learning&nbsp; →</button></section><div class="grid stat-grid"><div class="card stat-card"><div class="stat-top">Study time<span class="stat-icon">◷</span></div><div class="stat-number">${hours}<small>h </small>${minutes}<small>m</small></div><div class="stat-foot">Total time tracked</div></div><div class="card stat-card"><div class="stat-top">Study streak<span class="stat-icon">♨</span></div><div class="stat-number">${d.stats.streak}<small> days</small></div><div class="stat-foot">Active days this week</div></div><div class="card stat-card"><div class="stat-top">Lessons done<span class="stat-icon">✓</span></div><div class="stat-number">${d.stats.lessons}</div><div class="stat-foot">Across your courses</div></div><div class="card stat-card"><div class="stat-top">Memories saved<span class="stat-icon">◉</span></div><div class="stat-number">${d.stats.memories}</div><div class="stat-foot">Personalized learning context</div></div></div><div class="grid main-grid"><section class="card learning-card"><div class="card-head"><h3>Pick up your learning</h3><button class="text-link" onclick="go('courses')">All courses →</button></div><div class="course-list">${d.courses.length?d.courses.map(c=>`<div class="course-item"><div class="course-icon">▤</div><div class="course-info"><b>${esc(c.title)}</b><small>${esc(c.subject||'Independent study')}</small><div class="course-progress"><i style="width:0%"></i></div></div><span class="course-pct">New</span></div>`).join(''):`<div class="empty"><strong>Your learning path starts here</strong>Create a course for something you want to learn.<button class="btn primary" onclick="courseModal()">＋ Create a course</button></div>`}</div></section><section class="card"><div class="card-head"><h3>Recent study sessions</h3><button class="text-link" onclick="go('tutor')">Open tutor →</button></div><div class="activity-list">${d.recent.length?d.recent.map(c=>`<div class="activity-item"><div class="activity-mark">✧</div><div><b>${esc(c.title)}</b><small>${esc(c.subject||'Open study')} · ${esc(c.mode)} mode</small></div></div>`).join(''):`<div class="empty"><strong>No sessions yet</strong>Your saved tutoring conversations will appear here.</div>`}</div></section></div><div class="card wide-card"><div class="card-head"><h3>Your subjects</h3><button class="text-link" onclick="$('#addSubject').click()">＋ Add subject</button></div><div class="grid subject-grid">${d.subjects.map(s=>`<div class="card subject-card" onclick="studySubject=${s.id};go('tutor')" style="--c:${esc(s.color)}"><div class="subject-top"><span class="eyebrow">SUBJECT</span><i></i></div><b>${esc(s.name)}</b><small>${s.courses} courses</small></div>`).join('')}</div></div>`}
async function startSession(){const s=await api('/subjects');const options=s.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');modal('Start a study session',`<p class="modal-note">Track time while you study. You can stop the timer from the Insights page.</p><div class="field"><label>Subject</label><select id="sessionSubject"><option value="">Independent study</option>${options}</select></div>`,async()=>{const id=$('#sessionSubject').value;const start=Date.now();$('#content').insertAdjacentHTML('afterbegin',`<div class="card" id="timerBanner" style="margin-bottom:12px">Session in progress <b id="timer">00:00</b> <button class="btn" onclick="stopSession(${id||'null'},${start})">Finish session</button></div>`);window.__sessionTick=setInterval(()=>{const el=$('#timer');if(el){const sec=Math.floor((Date.now()-start)/1000);el.textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')}},1000)})}async function stopSession(id,start){clearInterval(window.__sessionTick);await post('/study-sessions',{subject_id:id,seconds:Math.max(1,Math.round((Date.now()-start)/1000))});toast('Study time saved');load()}
async function courseModal(){const s=await api('/subjects');modal('Create a course',`<div class="field"><label>Course name</label><input id="courseName" placeholder="e.g. Introduction to networking"></div><div class="field"><label>Subject</label><select id="courseSubject"><option value="">Choose a subject</option>${s.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`)}</select></div><div class="field"><label>What would you like to learn?</label><textarea id="courseDesc" placeholder="Add a focus, goal, or course description"></textarea></div><label class="modal-note"><input id="aiPath" type="checkbox"> Generate a structured learning path with Gemini</label>`,async()=>{const title=$('#courseName').value.trim(),subject_id=$('#courseSubject').value||null,description=$('#courseDesc').value.trim();if(!title)throw Error('Enter a course name.');if($('#aiPath').checked)await post('/ai/path',{text:`${title}. ${description}`,subject_id});else await post('/courses',{title,subject_id,description});toast('Course created');load()})}
async function courses(){await shared();const c=await api('/courses');$('#content').innerHTML=`<div class="title-row"><div><div class="eyebrow">YOUR CURRICULUM</div><h1>My learning</h1><div class="subline">Build a learning path, one lesson at a time.</div></div><div class="title-actions"><button class="btn primary" onclick="courseModal()">＋ Create course</button><button class="btn" onclick="pathModal()">✧ Generate learning path</button></div></div><div class="grid view-grid">${c.map(x=>`<section class="card"><div class="card-head"><div><span class="tag">${esc(x.subject||'Personal')}</span><h3>${esc(x.title)}</h3></div><button class="text-link" onclick="pathModal('${esc(x.title)}',${x.subject_id||'null'})">Add path ✧</button></div><p class="subline">${esc(x.description||'Your course workspace. Add lessons to get started.')}</p><div id="lessons-${x.id}" class="activity-list">Loading lessons…</div><div class="title-actions" style="margin-top:12px"><button class="btn" onclick="lessonModal(${x.id})">＋ Add lesson</button></div></section>`).join('')||`<div class="card empty"><strong>No courses yet</strong>Create a course or ask Gemini to create a complete learning path.<button class="btn primary" onclick="courseModal()">＋ Create course</button></div>`}</div>`;for(const x of c){const ls=await api('/courses/'+x.id+'/lessons');$('#lessons-'+x.id).innerHTML=ls.map(l=>`<div class="activity-item"><input type="checkbox" ${l.completed?'checked':''} onchange="toggleLesson(${l.id},this.checked)"><div><b>${esc(l.title)}</b><small>${esc(l.content.slice(0,110)||'Lesson content will appear here')}</small></div></div>`).join('')||'<div class="muted" style="padding:8px;font-size:11px">No lessons yet.</div>'}}
async function lessonModal(id){modal('Add a lesson',`<div class="field"><label>Lesson title</label><input id="lessonTitle"></div><div class="field"><label>Lesson content</label><textarea id="lessonContent"></textarea></div>`,async()=>{if(!$('#lessonTitle').value.trim())throw Error('Add a lesson title.');await post('/courses/'+id+'/lessons',{title:$('#lessonTitle').value,content:$('#lessonContent').value});load()})}async function toggleLesson(id,completed){await api('/lessons/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({completed})});toast(completed?'Lesson marked complete':'Lesson reopened')}async function pathModal(title='',subject_id=null){const s=await api('/subjects');modal('Generate a learning path',`<p class="modal-note">Gemini will create a structured course with lesson explanations and exercises. Requires your Gemini API key.</p><div class="field"><label>Learning goal</label><input id="pathTitle" value="${esc(title)}" placeholder="e.g. Learn physics from beginner to advanced"></div><div class="field"><label>Subject</label><select id="pathSubject"><option value="">Choose a subject</option>${s.map(x=>`<option value="${x.id}" ${x.id===subject_id?'selected':''}>${esc(x.name)}</option>`)}</select></div>`,async()=>{const t=$('#pathTitle').value.trim();if(!t)throw Error('Enter a learning goal.');const b=$('#modalSave');b.textContent='Generating…';b.disabled=true;await post('/ai/path',{text:t,subject_id:$('#pathSubject').value||null});toast('Learning path created');load()})}
async function tutor(){const {subs}=await shared();const list=await api('/conversations');if(currentConv&&!list.some(c=>c.id===currentConv))currentConv=null;$('#content').innerHTML=`<div class="title-row"><div><div class="eyebrow">A PATIENT TEACHER, ALWAYS ON</div><h1>AI tutor</h1><div class="subline">Learn, practice, ask for a hint, or explore a tricky idea together.</div></div><button class="btn primary" id="newChat">＋ New conversation</button></div><div class="chat-layout"><aside class="card chat-history"><h3>Recent conversations</h3><div id="history">${list.map(c=>`<div class="history-item ${currentConv===c.id?'sel':''}" data-conv="${c.id}" title="${esc(c.title)}">${esc(c.title)}</div>`).join('')||'<div class="muted" style="padding:8px;font-size:10px">Conversations you save appear here.</div>'}</div></aside><section class="card chat-panel"><div class="chat-tools"><select id="tutorMode"><option value="learn">Learn mode</option><option value="practice">Practice mode</option><option value="explain">Explain mode</option><option value="exam">Exam mode</option><option value="socratic">Socratic mode</option></select><select id="tutorSubject" class="subject-select"><option value="">Open study</option>${subs.map(s=>`<option value="${s.id}" ${studySubject===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><button class="text-link" id="hintBtn">Give me a hint</button><button class="text-link" id="solveBtn">Problem solver</button></div><div id="chatMessages" class="chat-messages"><div class="empty"><strong>What are you curious about?</strong>Pick a subject and ask your first question. Your conversations are saved automatically.</div></div><div class="chat-compose"><textarea id="chatInput" placeholder="Ask a question, paste a problem, or say ‘remember that…’"></textarea><button id="sendChat" class="btn primary">Send ↗</button></div><div class="tip">Your learning memory is included when relevant · Enter to send · Shift + Enter for a new line</div></section></div>`;$('#history').onclick=async e=>{const id=e.target.closest('[data-conv]')?.dataset.conv;if(id){currentConv=Number(id);await showConversation(currentConv)}};$('#newChat').onclick=()=>{currentConv=null;$('#chatMessages').innerHTML='<div class="empty"><strong>New conversation</strong>Ask a question and I’ll be here to help.</div>'};$('#sendChat').onclick=sendTutor;$('#chatInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendTutor()}};$('#hintBtn').onclick=()=>{$('#tutorMode').value='socratic';$('#chatInput').value='Give me a hint for: '+($('#chatInput').value||'the problem I am working on');$('#chatInput').focus()};$('#solveBtn').onclick=()=>{const val=$('#chatInput').value;modal('Solve a problem',`<p class="modal-note">Gemini will show the approach, steps, reasoning, and a check. Keep your attempt private until you want the solution.</p><div class="field"><label>Problem</label><textarea id="problemText">${esc(val)}</textarea></div><button class="btn" id="hintOnly">Ask for a hint only</button><div id="solveResult" class="modal-note" style="white-space:pre-wrap;margin-top:12px"></div>`,async()=>{});$('#modalSave').textContent='Solve problem';$('#modalSave').onclick=async()=>{const b=$('#modalSave');b.disabled=true;b.textContent='Solving…';try{const x=await post('/ai/solve',{text:$('#problemText').value});$('#solveResult').textContent=x.text;b.disabled=false;b.textContent='Done';b.onclick=()=>$('#modal').close()}catch(e){b.disabled=false;b.textContent='Solve problem';toast(e.message)}};$('#hintOnly').onclick=async()=>{try{const x=await post('/ai/solve',{text:'Give only one helpful hint, do not reveal the answer. Problem: '+$('#problemText').value});$('#solveResult').textContent=x.text}catch(e){toast(e.message)}}};if(currentConv)await showConversation(currentConv)}
async function showConversation(id){const d=await api('/conversations/'+id);$('#chatMessages').innerHTML=d.messages.map(m=>`<div class="message ${m.role==='assistant'?'assistant':'user'}">${esc(m.content)}</div>`).join('');$('#chatMessages').scrollTop=999999;currentConv=id}async function sendTutor(){const input=$('#chatInput'),text=input.value.trim();if(!text)return;const messages=$('#chatMessages');messages.querySelector('.empty')?.remove();messages.insertAdjacentHTML('beforeend',`<div class="message user">${esc(text)}</div><div class="message assistant" id="pending">Thinking through it…</div>`);input.value='';messages.scrollTop=messages.scrollHeight;$('#sendChat').disabled=true;try{const x=await post('/tutor',{conversation_id:currentConv,message:text,subject_id:$('#tutorSubject').value||null,mode:$('#tutorMode').value});currentConv=x.conversation_id;$('#pending').remove();messages.insertAdjacentHTML('beforeend',`<div class="message assistant">${esc(x.answer)}</div>`);messages.scrollTop=messages.scrollHeight}catch(e){$('#pending').classList.add('system');$('#pending').textContent=e.message}finally{$('#sendChat').disabled=false}}
async function notes(){const {status}=await shared();const [ns,docs,subjects]=await Promise.all([api('/notes'),api('/documents'),api('/subjects')]);$('#content').innerHTML=`<div class="title-row"><div><div class="eyebrow">YOUR PERSONAL LIBRARY</div><h1>Notes & library</h1><div class="subline">Upload a PDF or notes file, keep the original, and let Gemini turn it into a study guide.</div></div><button class="btn primary" onclick="noteModal()">＋ New note</button></div><div class="grid view-grid"><section class="card"><div class="card-head"><h3>Study notes</h3><button class="text-link" onclick="generateFromNote()">✧ Make notes from pasted text</button></div>${ns.map(n=>`<div class="memory-row"><div><span class="tag">${esc(n.subject||'Personal')}</span><div class="memory-copy"><b>${esc(n.title)}</b><br>${esc(n.body.slice(0,180))}${n.body.length>180?'…':''}</div></div><div class="memory-actions"><button class="tiny-btn" onclick="viewNote(${n.id})">Open</button><button class="tiny-btn" onclick="deleteNote(${n.id})">Delete</button></div></div>`).join('')||'<div class="empty"><strong>Your AI-generated notes will appear here</strong>Upload a document or paste class notes to get started.</div>'}</section><section class="card"><div class="card-head"><h3>Upload a document</h3><span class="tag">Max 12 MB</span></div><p class="modal-note">Accepted: PDF, DOCX, TXT, Markdown. Text is extracted on this computer. Scanned image PDFs need OCR and are not supported yet.</p><div class="doc-upload">Choose a file from your computer<input type="file" id="docUpload" accept=".pdf,.docx,.txt,.md"></div><div class="field"><label>Save it under a subject</label><select id="docSubject"><option value="">Personal library</option>${subjects.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><label class="modal-note"><input type="checkbox" id="docGenerateNotes" checked> Have Gemini create and save study notes after upload</label><p class="modal-note" style="margin-top:12px">${status.b2Configured?`Original files are stored in your private Backblaze B2 bucket <b>${esc(status.b2Bucket)}</b>.`:'Backblaze is not connected yet. Files will be kept in this app folder until you add the B2 settings.'} ${status.aiConfigured?'Gemini is ready to generate notes.':'Gemini is not configured, so files can be saved but AI notes will wait until Gemini is configured.'}</p><div class="card-head" style="margin-top:22px"><h3>Uploaded files</h3><button class="text-link" onclick="refreshNotes()">Refresh</button></div><div class="activity-list">${docs.map(d=>`<div class="memory-row"><div class="memory-copy"><b>${esc(d.name)}</b><div><small class="muted">${d.storage_backend==='backblaze'?'Backblaze B2':'Local copy'} · ${d.size_bytes?`${(d.size_bytes/1024/1024).toFixed(1)} MB`:'saved'}</small></div>${d.note_title?`<span class="tag" style="margin-top:7px">Notes ready: ${esc(d.note_title)}</span>`:'<small class="muted">No AI notes yet</small>'}</div><div class="memory-actions"><a class="tiny-btn" href="/api/documents/${d.id}/download">Download</a>${d.note_id?`<button class="tiny-btn" onclick="viewNote(${d.note_id})">Read notes</button>`:`<button class="tiny-btn" onclick="makeDocumentNotes(${d.id},event)">Make notes</button>`}<button class="tiny-btn" onclick="deleteDocument(${d.id})">Delete</button></div></div>`).join('')||'<div class="muted" style="padding:10px;font-size:11px">No files uploaded yet.</div>'}</div><div class="field" style="margin-top:24px"><label>Or paste your class notes</label><textarea id="sourceText" placeholder="Paste a lesson, notes, or transcript…"></textarea></div><button class="btn" onclick="summarizeSource()">✧ Generate study notes</button><button class="btn" onclick="generateCardsFromSource()">Create flashcards</button></section></div>`;
$('#content').insertAdjacentHTML('afterbegin',`<section class="card youtube-notes-card"><div class="card-head"><div><h3>Make notes from a YouTube video</h3><p class="modal-note">Paste a public video link. Gemini will create a study guide with a visual diagram and save it here.</p></div><span class="tag">✧ Gemini</span></div><div class="youtube-notes-form"><input id="youtubeUrl" type="url" placeholder="https://www.youtube.com/watch?v=…" aria-label="YouTube video link"><button class="btn primary" id="youtubeNotesBtn" onclick="generateYoutubeNotes()">Create video notes</button></div></section>`);
$('#youtubeUrl').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();generateYoutubeNotes()}});
$('#docUpload').onchange=async e=>{const file=e.target.files[0];if(!file)return;const fd=new FormData();fd.append('file',file);fd.append('subject_id',$('#docSubject').value);fd.append('generate_notes',$('#docGenerateNotes').checked?'true':'false');const zone=e.target.closest('.doc-upload');zone.classList.add('busy');try{const result=await api('/documents',{method:'POST',body:fd});if(result.generatedNote)toast(`Uploaded to ${result.storage==='backblaze'?'Backblaze B2':'your computer'} and saved AI notes`);else if(result.noteError)toast(`File saved. ${result.noteError}`);else toast(`File saved to ${result.storage==='backblaze'?'Backblaze B2':'your computer'}`);await notes()}catch(err){toast(err.message);zone.classList.remove('busy');e.target.value=''}}
}
async function refreshNotes(){await notes()}
function renderStudyNotes(source){let text=String(source||'');const diagrams=[];text=text.replace(/```study-diagram\s*([\s\S]*?)```/gi,(_,raw)=>{let d;try{d=JSON.parse(raw)}catch{return '\n[Diagram could not be displayed]\n'}const nodes=Array.isArray(d.nodes)?d.nodes.slice(0,12):[],edges=Array.isArray(d.edges)?d.edges:[];if(!nodes.length)return '';const flow=nodes.map((n,i)=>{const next=edges.find(e=>Number(e.from)===i&&Number(e.to)===i+1);return `<div class="study-diagram-node"><b>${esc(n.label||`Step ${i+1}`)}</b>${n.detail?`<span>${esc(n.detail)}</span>`:''}</div>${i<nodes.length-1?`<div class="study-diagram-arrow" aria-hidden="true"><span>→</span>${next?.label?`<small>${esc(next.label)}</small>`:''}</div>`:''}`}).join('');diagrams.push(`<section class="study-diagram"><h3>${esc(d.title||'Visual guide')}</h3><div class="study-diagram-flow">${flow}</div></section>`);return `\n@@DIAGRAM${diagrams.length-1}@@\n`});let html=esc(text).split(/\n/).map(line=>{const t=line.trim();if(!t)return '';if(/^@@DIAGRAM\d+@@$/.test(t))return t;if(/^###\s/.test(t))return `<h3>${t.slice(4)}</h3>`;if(/^##\s/.test(t))return `<h2>${t.slice(3)}</h2>`;if(/^#\s/.test(t))return `<h1>${t.slice(2)}</h1>`;if(/^[-*]\s/.test(t))return `<li>${t.slice(2)}</li>`;if(/^\d+\.\s/.test(t))return `<li>${t.replace(/^\d+\.\s/,'')}</li>`;if(/^&gt;\s/.test(t))return `<blockquote>${t.slice(5)}</blockquote>`;return `<p>${t}</p>`}).join('').replace(/<li>[\s\S]*?<\/li>(?:<li>[\s\S]*?<\/li>)*/g,m=>`<ul>${m}</ul>`).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');return html.replace(/@@DIAGRAM(\d+)@@/g,(_,i)=>diagrams[Number(i)]||'')}
async function viewNote(id){const n=await api('/notes/'+id),needsDiagram=!/```study-diagram\s*[\s\S]*?```/i.test(n.body);modal(n.title,`<div class="modal-note">${esc(n.subject||'Personal notes')}${n.source_url?` · <a href="${esc(n.source_url)}" target="_blank" rel="noopener">Open source video ↗</a>`:''}</div><article class="study-note-body">${renderStudyNotes(n.body)}</article>${needsDiagram?'<button class="btn" id="addNoteDiagram">✧ Add a visual diagram</button>':''}`,async()=>{});$('#modalSave').style.display='none';$('#modal').querySelector('.btn.ghost').textContent='Close';if(needsDiagram)$('#addNoteDiagram').onclick=()=>enhanceNoteDiagram(id)}
async function enhanceNoteDiagram(id){const b=$('#addNoteDiagram');if(b){b.disabled=true;b.textContent='Making diagram…'}try{await post('/notes/'+id+'/diagram',{});toast('Diagram added to your note');$('#modal').close();await viewNote(id)}catch(e){toast(e.message);if(b){b.disabled=false;b.textContent='✧ Add a visual diagram'}}}
async function generateYoutubeNotes(){const input=$('#youtubeUrl'),button=$('#youtubeNotesBtn'),url=input.value.trim();if(!url)return toast('Paste a YouTube video link first.');button.disabled=true;button.textContent='Gemini is watching…';try{const result=await post('/notes/youtube',{url,subject_id:$('#docSubject')?.value||null});toast('Video notes and diagram saved');await notes();if(result.note?.id)viewNote(result.note.id)}catch(e){toast(e.message)}finally{const b=$('#youtubeNotesBtn');if(b){b.disabled=false;b.textContent='Create video notes'}}}
async function makeDocumentNotes(id,ev){const b=ev.currentTarget;b.setAttribute('disabled','disabled');b.textContent='Generating…';try{await post('/documents/'+id+'/notes',{});toast('Study notes generated and saved');await notes()}catch(e){toast(e.message);b.removeAttribute('disabled');b.textContent='Make notes'}}
async function deleteDocument(id){if(!confirm('Delete this uploaded file from your library and storage?'))return;try{await api('/documents/'+id,{method:'DELETE'});toast('Uploaded file deleted');await notes()}catch(e){toast(e.message)}}
async function noteModal(){const s=await api('/subjects');modal('Write a note',`<div class="field"><label>Title</label><input id="noteTitle" placeholder="Class notes"></div><div class="field"><label>Subject</label><select id="noteSubject"><option value="">Personal</option>${s.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`)}</select></div><div class="field"><label>Note</label><textarea id="noteBody" style="min-height:180px"></textarea></div>`,async()=>{await post('/notes',{title:$('#noteTitle').value||'Untitled note',subject_id:$('#noteSubject').value||null,body:$('#noteBody').value});notes()})}async function deleteNote(id){if(confirm('Delete this note?')){await api('/notes/'+id,{method:'DELETE'});notes()}}async function summarizeSource(){const text=$('#sourceText').value.trim();if(!text)return toast('Paste some source text first.');try{await post('/notes/generate',{text,subject_id:$('#docSubject')?.value||null,title:'Study notes · '+new Date().toLocaleDateString()});toast('Study notes generated and saved');notes()}catch(e){toast(e.message)}}
async function generateFromNote(){modal('Generate study notes',`<div class="field"><label>Source text</label><textarea id="genText" placeholder="Paste text to turn into structured notes"></textarea></div><p class="modal-note">Gemini will organize the text into a study guide and save it to your library.</p>`,async()=>{const text=$('#genText').value.trim();if(!text)throw Error('Paste some source text first.');await post('/notes/generate',{text,title:'Generated study notes'});toast('Study notes generated and saved');notes()})}
async function flashcards(){const {due}=await shared(),decks=await api('/decks');activeCard=activeCard&&due.find(c=>c.id===activeCard.id)||due[0]||null;revealed=false;$('#content').innerHTML=`<div class="title-row"><div><div class="eyebrow">SPACED REPETITION</div><h1>Flashcards</h1><div class="subline">A little recall each day makes knowledge stick.</div></div><div class="title-actions"><button class="btn" onclick="deckModal()">＋ New deck</button><button class="btn primary" onclick="cardModal()">＋ Add flashcard</button></div></div><div class="grid view-grid"><section><div class="card flashcard" id="flashcard"><div class="eyebrow">${activeCard?`DUE · ${esc(activeCard.deck)}`:'DAILY REVIEW'}</div><h2>${activeCard?esc(revealed?activeCard.back:activeCard.front):'You’re all caught up.'}</h2><p>${activeCard?(revealed?'How well did you know this?':'Tap the card to reveal the answer'):'Create a deck and cards to start spaced review.'}</p></div>${activeCard&&revealed?`<div class="rating-row"><button class="btn" onclick="reviewCard(1)">Forgot</button><button class="btn" onclick="reviewCard(3)">Hard</button><button class="btn" onclick="reviewCard(4)">Good</button><button class="btn primary" onclick="reviewCard(5)">Easy</button></div>`:''}<div class="subline" style="text-align:center;margin-top:15px">${due.length} cards due today</div></section><section class="card"><div class="card-head"><h3>Your decks</h3><span class="tag">${decks.reduce((a,d)=>a+d.cards,0)} cards total</span></div>${decks.map(d=>`<div class="activity-item"><div class="activity-mark">▱</div><div><b>${esc(d.title)}</b><small>${esc(d.subject||'Personal')} · ${d.cards} cards</small></div></div>`).join('')||'<div class="empty"><strong>No decks yet</strong>Create flashcards by hand or generate from notes.</div>'}</section></div>`;$('#flashcard').onclick=()=>{if(activeCard){revealed=!revealed;flashcards()}}}
async function deckModal(){const s=await api('/subjects');modal('Create a flashcard deck',`<div class="field"><label>Deck name</label><input id="deckTitle"></div><div class="field"><label>Subject</label><select id="deckSubject"><option value="">Personal</option>${s.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`)}</select></div>`,async()=>{if(!$('#deckTitle').value.trim())throw Error('Enter a deck name.');await post('/decks',{title:$('#deckTitle').value,subject_id:$('#deckSubject').value||null});flashcards()})}async function cardModal(){let ds=await api('/decks');if(!ds.length){await post('/decks',{title:'My flashcards'});ds=await api('/decks')}modal('Add a flashcard',`<div class="field"><label>Deck</label><select id="cardDeck">${ds.map(d=>`<option value="${d.id}">${esc(d.title)}</option>`).join('')}</select></div><div class="field"><label>Front</label><textarea id="cardFront"></textarea></div><div class="field"><label>Back</label><textarea id="cardBack"></textarea></div>`,async()=>{await post('/flashcards',{deck_id:$('#cardDeck').value,front:$('#cardFront').value,back:$('#cardBack').value});toast('Flashcard saved');flashcards()})}async function reviewCard(rating){await post('/flashcards/'+activeCard.id+'/review',{rating});activeCard=null;flashcards()}async function generateCardsFromSource(){const text=$('#sourceText').value.trim();if(!text)return toast('Paste source text first.');try{await post('/ai/flashcards',{text});toast('Flashcards created');flashcards()}catch(e){toast(e.message)}}
async function memory(){const subjects=await api('/subjects');const filter=$('#memoryFilter')?.value||'';const q=$('#memorySearch')?.value||'';const mem=await api('/memories?'+(filter?'subject='+encodeURIComponent(filter):'')+(q?'&q='+encodeURIComponent(q):''));$('#content').innerHTML=`<div class="title-row"><div><div class="eyebrow">PERSISTENT, PRIVATE, YOURS</div><h1>Learning memory</h1><div class="subline">The context your tutor uses across conversations.</div></div><div class="title-actions"><button class="btn" onclick="clearMemory()">Clear all</button><button class="btn primary" onclick="memoryModal()">＋ Add memory</button></div></div><div class="toolbar"><input id="memorySearch" placeholder="Search saved memories…" value="${esc(q)}"><select id="memoryFilter"><option value="">All subjects & personal</option><option value="personal" ${filter==='personal'?'selected':''}>Personal preferences</option>${subjects.map(s=>`<option value="${esc(s.name)}" ${filter===s.name?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><section class="card">${mem.map(m=>`<div class="memory-row"><div class="memory-copy"><span class="tag">${esc(m.subject||m.category)}</span> <span class="tag" style="background:#242821;color:#b7beb0">${esc(m.source)}</span><div>${esc(m.content)}</div><small class="muted">Updated ${new Date(m.updated_at+'Z').toLocaleDateString()}</small></div><div class="memory-actions"><button class="tiny-btn" onclick="editMemory(${m.id},${JSON.stringify(m.content).replace(/'/g,'&#39;')})">Edit</button><button class="tiny-btn" onclick="deleteMemory(${m.id})">Forget</button></div></div>`).join('')||'<div class="empty"><strong>No saved memories match</strong>Ask your tutor to “remember that…” or add one here.</div>'}</section><p class="subline" style="margin-top:12px">Memories are stored in your local database. Explicit “remember that…” instructions are saved immediately.</p>`;$('#memorySearch').oninput=()=>memory();$('#memoryFilter').onchange=()=>memory()}
async function memoryModal(){const s=await api('/subjects');modal('Add a learning memory',`<div class="field"><label>Memory</label><textarea id="memoryText" placeholder="I prefer simple explanations with practical examples."></textarea></div><div class="field"><label>Applies to</label><select id="memorySubject"><option value="">Personal preference</option>${s.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`)}</select></div><div class="field"><label>Category</label><select id="memoryCategory"><option>preference</option><option>learning</option><option>strength</option><option>difficulty</option><option>goal</option></select></div>`,async()=>{await post('/memories',{content:$('#memoryText').value,subject_id:$('#memorySubject').value||null,category:$('#memoryCategory').value});memory()})}async function editMemory(id,content){modal('Edit memory',`<div class="field"><label>Memory content</label><textarea id="editMemoryText">${esc(content)}</textarea></div>`,async()=>{await api('/memories/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:$('#editMemoryText').value})});memory()})}async function deleteMemory(id){await api('/memories/'+id,{method:'DELETE'});toast('Memory deleted');memory()}async function clearMemory(){if(confirm('Permanently clear every saved learning memory?')){await api('/memories',{method:'DELETE'});toast('All memories cleared');memory()}}
async function analytics(){const [a,d]=await Promise.all([api('/analytics'),api('/dashboard')]);const days=Array.from({length:14},(_,i)=>{const date=new Date();date.setDate(date.getDate()-13+i);const key=date.toISOString().slice(0,10);return{day:key,seconds:a.daily.find(x=>x.day===key)?.seconds||0}});const max=Math.max(1,...days.map(x=>x.seconds));$('#content').innerHTML=`<div class="title-row"><div><div class="eyebrow">YOUR LEARNING, OVER TIME</div><h1>Insights</h1><div class="subline">A clear picture of the habits you’re building.</div></div><button class="btn" onclick="startSession()">◷ Track study time</button></div><div class="grid stat-grid"><div class="card stat-card"><div class="stat-top">Total study time<span class="stat-icon">◷</span></div><div class="stat-number">${Math.floor(d.stats.seconds/3600)}<small>h </small>${Math.floor(d.stats.seconds%3600/60)}<small>m</small></div></div><div class="card stat-card"><div class="stat-top">Completed lessons<span class="stat-icon">✓</span></div><div class="stat-number">${d.stats.lessons}</div></div><div class="card stat-card"><div class="stat-top">Quiz attempts<span class="stat-icon">▤</span></div><div class="stat-number">${d.stats.quizzes}</div></div><div class="card stat-card"><div class="stat-top">Current streak<span class="stat-icon">♨</span></div><div class="stat-number">${d.stats.streak}<small> days</small></div></div></div><div class="grid view-grid"><section class="card"><div class="card-head"><h3>Study time · last 14 days</h3></div><div class="chart">${days.map(x=>`<div class="bar-wrap"><div class="bar" style="height:${Math.max(x.seconds?4:1,x.seconds/max*100)}%" title="${Math.round(x.seconds/60)} min"></div><small>${new Date(x.day+'T00:00').toLocaleDateString(undefined,{weekday:'short'})}</small></div>`).join('')}</div><p class="subline">Only sessions you track appear here.</p></section><section class="card"><div class="card-head"><h3>Quiz history</h3></div>${a.attempts.map(x=>`<div class="activity-item"><div class="activity-mark">✓</div><div><b>${x.score}/${x.total} correct</b><small>${new Date(x.created_at+'Z').toLocaleDateString()}</small></div></div>`).join('')||'<div class="empty"><strong>No quiz attempts yet</strong>Your results will appear here.</div>'}</section></div><section class="card wide-card"><div class="card-head"><h3>Subject activity</h3></div>${a.subjects.map(x=>`<div class="memory-row"><div><b>${esc(x.name)}</b><div class="subline">${x.lessons} lessons · ${x.attempts} quiz attempts</div></div><span class="tag">${x.score==null?'No scores':Math.round(x.score)+'% avg'}</span></div>`).join('')}</section>`}
async function settings(){const [s,status]=await Promise.all([api('/settings'),api('/status')]);$('#content').innerHTML=`<div class="title-row"><div><div class="eyebrow">MAKE THIS SPACE YOURS</div><h1>Settings</h1><div class="subline">Your preferences and private study data.</div></div><button class="btn" onclick="location.href='/api/export'">↓ Export backup</button></div><div class="grid view-grid"><section class="card"><div class="card-head"><h3>Study preferences</h3></div><div class="field"><label>Explanation detail</label><select id="prefExplain"><option value="simple" ${s.explanation==='simple'?'selected':''}>Very simple</option><option value="intermediate" ${!s.explanation||s.explanation==='intermediate'?'selected':''}>Intermediate</option><option value="advanced" ${s.explanation==='advanced'?'selected':''}>Advanced detail</option></select></div><div class="field"><label>Preferred language</label><input id="prefLanguage" value="${esc(s.language||'English')}"></div><div class="field"><label>Default quiz difficulty</label><select id="prefDifficulty"><option ${s.defaultDifficulty==='easy'?'selected':''}>easy</option><option ${!s.defaultDifficulty||s.defaultDifficulty==='medium'?'selected':''}>medium</option><option ${s.defaultDifficulty==='hard'?'selected':''}>hard</option></select></div><label class="modal-note"><input type="checkbox" id="autoMemory" ${s.autoMemory!=='false'?'checked':''}> Allow automatic AI memory creation (when Gemini is configured)</label><div style="margin-top:15px"><button class="btn primary" id="savePrefs">Save preferences</button></div></section><section class="card"><div class="card-head"><h3>Gemini connection</h3><span class="tag">${status.aiConfigured?'Connected':'Not configured'}</span></div><p class="modal-note">AI runs through Google Gemini on this server. Your API key stays in your local <code>.env</code> file and is never sent to the browser.</p><div class="field"><label>Model</label><input disabled value="${esc(status.model)}"></div><p class="modal-note">To enable Gemini: copy <code>.env.example</code> to <code>.env</code>, add your Google AI Studio API key as <code>GEMINI_API_KEY</code>, then restart the app.</p></section><section class="card"><div class="card-head"><h3>Appearance</h3></div><p class="modal-note">Switch between dark and light themes using the ◐ button in the top bar.</p><button class="btn" onclick="$('#themeBtn').click()">◐ Toggle theme</button></section><section class="card"><div class="card-head"><h3>Data & privacy</h3></div><p class="modal-note">Your study data is stored in your private account database under <code>data/users</code>. Export a JSON backup at any time.</p><button class="btn" onclick="location.href='/api/export'">Download data backup</button></section></div>`;$('#content').insertAdjacentHTML('afterbegin',`<section class="card account-card"><div class="card-head"><h3>Account</h3><span class="tag">Private workspace</span></div><p class="modal-note">Signed in as <b>${esc(status.account?.email||'')}</b>. Your notes, files, and study history are stored separately from other accounts.</p><button class="btn ghost" style="margin-left:7px" onclick="logout()">Sign out</button></section>`);$('.account-card').insertAdjacentHTML('beforeend',`<form id="passwordForm" class="account-password-form"><h3>Change password</h3><div class="field"><label>Current password</label><input name="currentPassword" type="password" autocomplete="current-password" required></div><div class="field"><label>New password (at least 10 characters)</label><input name="newPassword" type="password" autocomplete="new-password" minlength="10" maxlength="200" required></div><button class="btn" type="submit">Change password</button><span id="passwordMessage" class="modal-note"></span></form>`);$('#passwordForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),b=e.currentTarget.querySelector('button');b.disabled=true;try{await post('/account/password',{currentPassword:f.get('currentPassword'),newPassword:f.get('newPassword')});e.currentTarget.reset();$('#passwordMessage').textContent='Password changed. Other sign-ins were ended.';toast('Password changed')}catch(err){$('#passwordMessage').textContent=err.message}finally{b.disabled=false}};$('#savePrefs').onclick=async()=>{await put('/settings',{explanation:$('#prefExplain').value,language:$('#prefLanguage').value,defaultDifficulty:$('#prefDifficulty').value,autoMemory:$('#autoMemory').checked});toast('Preferences saved')}}
async function quizzes(){await shared();const qs=await api('/quizzes');$('#content').innerHTML=`<div class="title-row"><div><div class="eyebrow">PRACTICE THAT ADAPTS</div><h1>Quizzes & exams</h1><div class="subline">Make practice questions from your material and learn from every attempt.</div></div><button class="btn primary" onclick="quizModal()">✧ Generate quiz</button></div><div class="grid view-grid">${qs.map(q=>`<section class="card"><div class="card-head"><div><span class="tag">${esc(q.subject||'Personal')}</span><h3>${esc(q.title)}</h3></div><span class="muted">${q.count||0} questions</span></div><button class="btn primary" onclick="takeQuiz(${q.id})">Start quiz →</button></section>`).join('')||'<div class="card empty"><strong>No quizzes yet</strong>Generate a quiz from a subject or your own notes. Gemini required.<button class="btn primary" onclick="quizModal()">✧ Generate quiz</button></div>'}</div>`}
async function quizModal(){const s=await api('/subjects');modal('Generate a quiz',`<p class="modal-note">A structured quiz will be generated and saved to your library. Requires Gemini API key.</p><div class="field"><label>Topic or source material</label><textarea id="quizSource" placeholder="e.g. Newton’s laws of motion, or paste lesson notes"></textarea></div><div class="field"><label>Subject</label><select id="quizSubject"><option value="">General</option>${s.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`)}</select></div><div class="grid view-grid"><div class="field"><label>Questions</label><input id="quizCount" type="number" min="1" max="20" value="5"></div><div class="field"><label>Difficulty</label><select id="quizDifficulty"><option>easy</option><option selected>medium</option><option>hard</option></select></div></div>`,async()=>{const text=$('#quizSource').value.trim();if(!text)throw Error('Add a topic or source text.');await post('/ai/quiz',{text,subject_id:$('#quizSubject').value||null,count:$('#quizCount').value,difficulty:$('#quizDifficulty').value});toast('Quiz generated');load()})}
async function takeQuiz(id){const q=await api('/quizzes/'+id);let i=0,answers=Array(q.questions.length).fill('');const draw=()=>{const x=q.questions[i];$('#content').innerHTML=`<div class="title-row"><div><div class="eyebrow">QUIZ · QUESTION ${i+1} OF ${q.questions.length}</div><h1>${esc(q.title)}</h1></div><button class="btn" onclick="go('quizzes')">Exit quiz</button></div><section class="card"><div class="eyebrow">${esc(x.topic)}</div><h2 style="font:600 19px Manrope;line-height:1.5">${esc(x.question)}</h2><div class="field">${x.options?.length?x.options.map((o,n)=>`<label class="activity-item"><input type="radio" name="answer" value="${esc(o)}" ${answers[i]===o?'checked':''}><span>${esc(o)}</span></label>`).join(''):`<textarea id="quizAnswer" placeholder="Your answer…">${esc(answers[i])}</textarea>`}</div><div class="title-actions"><button class="btn" id="prevQ" ${i===0?'disabled':''}>← Previous</button><button class="btn primary" id="nextQ">${i===q.questions.length-1?'Finish quiz':'Next question →'}</button></div></section>`;$('#prevQ').onclick=()=>{answers[i]=read();i--;draw()};$('#nextQ').onclick=async()=>{answers[i]=read();if(i<q.questions.length-1){i++;draw()}else{const result=await post('/quizzes/'+id+'/attempts',{answers});$('#content').innerHTML=`<div class="title-row"><div><div class="eyebrow">QUIZ COMPLETE</div><h1>${result.score} / ${result.total} correct</h1><div class="subline">${Math.round(result.score/result.total*100)}% · Review the answers and explanations below.</div></div><button class="btn primary" onclick="go('quizzes')">Done</button></div><section class="card">${result.results.map((a,n)=>`<div class="memory-row"><div class="memory-copy"><span class="tag">${a.correct?'Correct':'Review'}</span><b>${esc(a.question.question)}</b><div class="subline">Your answer: ${esc(a.user||'No answer')} · Correct answer: ${esc(a.question.answer)}</div><p>${esc(a.question.explanation)}</p></div></div>`).join('')}</section>`}}};function read(){return document.querySelector('input[name="answer"]:checked')?.value||$('#quizAnswer')?.value||''}draw()}
function renderAuth(mode,registrationOpen,error='',setupTokenRequired=false){const setup=mode==='setup',register=mode==='register';const gate=$('#authGate');gate.hidden=false;gate.innerHTML=`<section class="auth-card"><div class="auth-brand">studyspace<span>.</span></div><h1>${setup?'Create your private workspace':register?'Create your separate account':'Welcome back'}</h1><p>${setup?'Create the owner account. Your existing Studyspace data will be kept in this account.':register?'Choose an email and password. Your study data will be kept separate from every other account.':'Sign in to your personal Studyspace.'}</p><form id="authForm"><div class="field"><label>Email</label><input name="email" type="email" autocomplete="email" required maxlength="254"></div><div class="field"><label>Password${register||setup?' (at least 10 characters)':''}</label><input name="password" type="password" autocomplete="${register||setup?'new-password':'current-password'}" required minlength="10" maxlength="200"></div>${setup&&setupTokenRequired?'<div class="field"><label>Server setup token</label><input name="setupToken" autocomplete="off" required></div>':''}<div class="auth-error" id="authError">${esc(error)}</div><button class="btn primary" style="width:100%" type="submit">${setup?'Create owner account':register?'Create my account':'Sign in'}</button></form>${!setup?`<button class="auth-toggle" id="authToggle">${register?'Already have an account? Sign in':'New here? Create an account'}</button>`:''}</section>`;$('#authForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),button=e.currentTarget.querySelector('button[type=submit]');button.disabled=true;button.textContent='Please wait…';try{await post(register||setup?'/auth/register':'/auth/login',{email:f.get('email'),password:f.get('password'),setupToken:f.get('setupToken')||''});document.body.classList.add('signed-in');gate.hidden=true;await startApp()}catch(err){$('#authError').textContent=err.message;button.disabled=false;button.textContent=setup?'Create owner account':register?'Create my account':'Sign in'}};$('#authToggle')?.addEventListener('click',()=>renderAuth(register?'login':'register',registrationOpen))}
async function startApp(){try{const state=await api('/auth/me');if(!state.authenticated){document.body.classList.remove('signed-in');renderAuth(state.registrationOpen?'setup':'login',state.registrationOpen,'',state.setupTokenRequired);return}$('#authGate').hidden=true;document.body.classList.add('signed-in');const profile=document.querySelector('.profile b');if(profile)profile.textContent=state.account.email;await load()}catch(e){document.body.classList.remove('signed-in');renderAuth('login',false,'Could not connect to Studyspace. Check that its server is running and try again.')}}
async function logout(){await post('/auth/logout',{});document.body.classList.remove('signed-in');renderAuth('login',false)}
$('#addSubject').onclick=()=>modal('Add a subject',`<div class="field"><label>Subject name</label><input id="subjectName" placeholder="e.g. Cybersecurity"></div>`,async()=>{await post('/subjects',{name:$('#subjectName').value});load()});if(location.hash.slice(1))view=location.hash.slice(1);window.startStudyspaceApp=startApp;
function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function prettyDate(date){return new Date(`${date}T00:00:00`).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}
function eventTypeLabel(t){return t==='exam'?'Exam':t==='deadline'?'Deadline':'Study'}
async function appendUpcoming(){const events=await api('/calendar/upcoming');const host=$('#content');if(!host)return;host.insertAdjacentHTML('beforeend',`<section class="card wide-card"><div class="card-head"><h3>Coming up</h3><button class="text-link" onclick="go('calendar')">Open calendar →</button></div>${events.map(e=>`<div class="activity-item"><div class="activity-mark">${e.event_type==='exam'?'✎':e.event_type==='deadline'?'◷':'▦'}</div><div class="event-upcoming"><b>${esc(e.title)}</b><small>${prettyDate(e.event_date)}${e.start_time?' · '+esc(e.start_time):''} · ${esc(e.subject||eventTypeLabel(e.event_type))}</small></div><span class="tag">${eventTypeLabel(e.event_type)}</span></div>`).join('')||'<div class="muted" style="font-size:11px;padding:8px 0">No upcoming exams, deadlines, or study sessions. Add one to your calendar.</div>'}<button class="btn" style="margin-top:10px" onclick="eventModal(dateKey(new Date()))">＋ Add an event</button></section>`)}
async function calendar(){await shared();const month=dateKey(calendarCursor).slice(0,7);currentCalendarEvents=await api('/calendar?month='+month);const [y,m]=month.split('-').map(Number),first=new Date(y,m-1,1),offset=(first.getDay()+6)%7,start=new Date(y,m-1,1-offset),today=dateKey(new Date());const cells=Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const key=dateKey(d),items=currentCalendarEvents.filter(e=>e.event_date===key);return`<div class="calendar-day ${d.getMonth()===m-1?'':'outside'} ${key===today?'today':''}" data-date="${key}"><button class="day-number" data-date="${key}">${d.getDate()}</button><div class="day-events">${items.slice(0,3).map(e=>`<button class="calendar-event ${esc(e.event_type)}" data-event="${e.id}" title="${esc(e.title)}">${e.start_time?esc(e.start_time)+' ':''}${esc(e.title)}</button>`).join('')}${items.length>3?`<small>+${items.length-3} more</small>`:''}</div></div>`}).join('');$('#content').innerHTML=`<div class="title-row"><div><div class="eyebrow">PLAN YOUR STUDY TIME</div><h1>Study calendar</h1><div class="subline">Keep exams, deadlines, and study sessions in one place.</div></div><button class="btn primary" onclick="eventModal(dateKey(new Date()))">＋ Add event</button></div><section class="card calendar-card"><div class="calendar-toolbar"><div><button class="tiny-btn" id="calPrev">←</button><button class="tiny-btn" id="calToday">Today</button><button class="tiny-btn" id="calNext">→</button><b>${calendarCursor.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</b></div><span class="tag">${currentCalendarEvents.length} events</span></div><div class="calendar-weekdays"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span></div><div class="calendar-grid" id="calendarGrid">${cells}</div><div class="calendar-legend"><span><i class="exam"></i> Exams</span><span><i class="deadline"></i> Deadlines</span><span><i class="study"></i> Study sessions</span></div></section><div class="grid view-grid calendar-lower"><section class="card"><div class="card-head"><h3>This month</h3><button class="text-link" onclick="eventModal(dateKey(new Date()))">＋ Add</button></div>${currentCalendarEvents.map(e=>`<div class="memory-row"><div><span class="tag ${esc(e.event_type)}">${eventTypeLabel(e.event_type)}</span><div class="memory-copy"><b>${esc(e.title)}</b><small class="muted">${prettyDate(e.event_date)}${e.start_time?' · '+esc(e.start_time):''}${e.subject?' · '+esc(e.subject):''}</small>${e.description?`<div class="subline">${esc(e.description)}</div>`:''}</div></div><button class="tiny-btn" onclick="editCalendarEvent(${e.id})">Edit</button></div>`).join('')||'<div class="empty"><strong>No events this month</strong>Add an exam, deadline, or planned study session.</div>'}</section><section class="card"><div class="card-head"><h3>Plan ahead</h3></div><p class="modal-note">Calendar entries are saved on this computer and included in your data backup.</p><button class="btn" onclick="eventModal(dateKey(new Date()),null,'exam')">＋ Add an exam</button><button class="btn" onclick="eventModal(dateKey(new Date()),null,'deadline')">＋ Add a deadline</button><button class="btn" onclick="eventModal(dateKey(new Date()),null,'study')">＋ Schedule study time</button></section></div>`;$('#calPrev').onclick=()=>{calendarCursor=new Date(y,m-2,1);calendar()};$('#calNext').onclick=()=>{calendarCursor=new Date(y,m,1);calendar()};$('#calToday').onclick=()=>{calendarCursor=new Date();calendar()};$('#calendarGrid').onclick=e=>{const chip=e.target.closest('[data-event]');if(chip){editCalendarEvent(Number(chip.dataset.event));return}const day=e.target.closest('[data-date]');if(day)eventModal(day.dataset.date)} }
async function eventModal(date,eventId=null,type='study'){const existing=eventId?currentCalendarEvents.find(x=>x.id===eventId):null;if(eventId&&!existing){const all=await api('/calendar?month='+dateKey(calendarCursor).slice(0,7));currentCalendarEvents=all;return eventModal(date,eventId,type)}const subjects=await api('/subjects');modal(existing?'Edit calendar event':'Add calendar event',`<div class="field"><label>Event name</label><input id="eventTitle" maxlength="150" value="${esc(existing?.title||'')}" placeholder="e.g. Chemistry midterm"></div><div class="grid view-grid"><div class="field"><label>Type</label><select id="eventType"><option value="exam" ${(existing?.event_type||type)==='exam'?'selected':''}>Exam</option><option value="deadline" ${(existing?.event_type||type)==='deadline'?'selected':''}>Deadline</option><option value="study" ${(existing?.event_type||type)==='study'?'selected':''}>Study session</option></select></div><div class="field"><label>Date</label><input id="eventDate" type="date" value="${esc(existing?.event_date||date)}"></div></div><div class="grid view-grid"><div class="field"><label>Start time (optional)</label><input id="eventTime" type="time" value="${esc(existing?.start_time||'')}"></div><div class="field"><label>Subject (optional)</label><select id="eventSubject"><option value="">No subject</option>${subjects.map(s=>`<option value="${s.id}" ${existing?.subject_id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div></div><div class="field"><label>Details (optional)</label><textarea id="eventDescription" placeholder="Room, chapters, or reminders">${esc(existing?.description||'')}</textarea></div>${existing?'<button class="btn" id="deleteCalendarEvent" type="button">Delete event</button>':''}`,async()=>{const data={title:$('#eventTitle').value,event_type:$('#eventType').value,event_date:$('#eventDate').value,start_time:$('#eventTime').value,subject_id:$('#eventSubject').value||null,description:$('#eventDescription').value};if(existing)await api('/calendar-events/'+existing.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});else await post('/calendar-events',data);toast(existing?'Event updated':'Event added');await calendar()});if(existing)$('#deleteCalendarEvent').onclick=async()=>{if(confirm('Delete this calendar event?')){await api('/calendar-events/'+existing.id,{method:'DELETE'});$('#modal').close();toast('Event deleted');calendar()}}}
async function editCalendarEvent(id){const item=currentCalendarEvents.find(e=>e.id===id);if(item)return eventModal(item.event_date,id);const month=dateKey(calendarCursor).slice(0,7);currentCalendarEvents=await api('/calendar?month='+month);const match=currentCalendarEvents.find(e=>e.id===id);if(match)eventModal(match.event_date,id)}

function applyTheme(id){const t=THEMES.find(x=>x.id===id)||THEMES[0];document.body.dataset.theme=t.id;document.body.classList.toggle('light',t.light);const vars={bg:t.bg,panel:t.panel,panel2:t.panel2,line:t.line,text:t.text,muted:t.muted,green:t.accent,green2:t.accentLight,ink:t.ink};for(const [k,v] of Object.entries(vars))document.body.style.setProperty('--'+k,v);localStorage.setItem('studyspace-theme',t.id);const btn=$('#themeBtn');if(btn)btn.title=`Theme: ${t.name}`}
function openThemePicker(){const current=document.body.dataset.theme||'midnight';modal('Choose your theme',`<p class="modal-note">Pick a color palette for your study space. Your choice is saved on this device.</p><div class="theme-grid">${THEMES.map(t=>`<button type="button" class="theme-choice ${t.id===current?'selected':''}" data-theme-choice="${t.id}" aria-pressed="${t.id===current}"><span class="theme-swatches">${t.swatches.map(c=>`<i style="background:${c}"></i>`).join('')}</span><b>${t.name}</b><small>${t.light?'Light':'Dark'} theme${t.id==='lilies'?' · water lilies':t.id==='bunnies'?' · bunny meadow':''}</small></button>`).join('')}</div>`,async()=>{});$('#modal').classList.add('theme-picker');$('#modalSave').style.display='none';$('#modal').querySelector('.btn.ghost').textContent='Close';$('#modalBody').querySelector('.theme-grid').onclick=e=>{const choice=e.target.closest('[data-theme-choice]');if(!choice)return;applyTheme(choice.dataset.themeChoice);$('#modal').close();toast(`${THEMES.find(t=>t.id===choice.dataset.themeChoice).name} theme applied`)}}
